// CloudIT - Vercel Deployments Collector — Load Config.
// Purpose: compute the shared run constants and hold the plain (NON-SECRET)
// Vercel project identifiers. All timestamps are computed at RUN TIME —
// never hardcode a test clock: publishedAt must be within ±5 minutes of
// ingestion (0004 stale_timestamp).
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).

// The idempotency base is the CURRENT UTC hour rendered as
// 'vercel-deployments-YYYY-MM-DDTHH' (opaque; only uniqueness matters), so
// every hourly run upserts fresh rows. freshUntil is observedAt + 3h, the
// seeded hourly freshness. teamId/projectId are NOT secrets — the owner
// replaces the placeholders before activation.

const now = new Date();
const nowMs = now.getTime();
const HOUR_MS = 60 * 60 * 1000;
const DAY_MS = 24 * HOUR_MS;
const hourStart = new Date(Math.floor(nowMs / HOUR_MS) * HOUR_MS);
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());

return [{
  json: {
    teamId: 'team_REPLACE_ME',
    projectId: 'project_REPLACE_ME',
    todayStart: ymd(new Date(nowMs)) + 'T00:00:00.000Z',
    todayEnd: ymd(new Date(nowMs + DAY_MS)) + 'T00:00:00.000Z',
    observedAt: now.toISOString(),
    publishedAt: now.toISOString(),
    freshUntil: new Date(nowMs + 3 * 3600 * 1000).toISOString(),
    base: 'vercel-deployments-' + ymd(hourStart) + 'T' + pad(hourStart.getUTCHours())
  }
}];

// CloudIT - Vercel Deployments Collector — Normalize Deployments.
// Purpose: turn the deployments list and the project domains list into
// deployment_summary / metric_sample records plus the provider_connection —
// or, when either call failed, into the single failure provider_connection.
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).

// - ONLY items whose target field EXISTS and === 'production' are kept —
//   everything else is omitted (VERIFY-ON-FIRST-RUN: if the live /v7 schema
//   omits target entirely, check diagnostics.deploymentsOmittedNonTarget on
//   the first run before trusting the counts).
// - state maps ERROR->failed, CANCELED->cancelled, READY->ready,
//   BUILDING/INITIALIZING/QUEUED->building, anything else -> unknown.
// - durationMs = readyAt - createdAt only when BOTH are known, else omitted.
// - publicDomainKey = the first alias matching the domain regex, else omitted.
// - isCurrentProduction = true only for the NEWEST ready production
//   deployment by createdAt.
// - Domains: one vercel.domain.verified metric_sample per domain whose
//   lowercased name matches ^[a-z0-9.-]+\.[a-z]{2,}$; others are omitted.
//
// WIRING NOTE: this node reads the Get Deployments output via
// $('Get Deployments').first().json — safe because the chain is a single
// straight line executed exactly once (the proven Phase 6 v2 pattern: n8n
// HTTP nodes do not pass input fields through).

const config = $('Load Config').first().json;
const depResp = $('Get Deployments').first().json;
const domResp = $input.first().json;

// --- failure inspection -----------------------------------------------------
// A failed HTTP node (onError: continueRegularOutput) yields an item whose
// json is an error object; a 200 whose body is a provider error document
// carries an error field too. Anything that is not a confirmed healthy body
// counts as a failure; the status code is best-effort (network/timeout
// failures carry none -> category provider_unavailable, state unknown).
function failureOf(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    return { failed: true, status: null, timedOut: false };
  }
  const err = item.error
    ? (typeof item.error === 'object' ? item.error : { message: String(item.error) })
    : null;
  if (err === null) return { failed: false, status: null, timedOut: false };
  const msg = String(err.message || '') + ' ' + String(err.description || '');
  const timedOut = /timed?\s*out|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(msg) || err.code === 'ETIMEDOUT';
  let status = null;
  for (const c of [err.statusCode, err.httpCode, item.statusCode]) {
    const n = typeof c === 'string' ? parseInt(c, 10) : c;
    if (Number.isInteger(n) && n >= 100 && n <= 599) { status = n; break; }
  }
  if (status === null) {
    const m = msg.match(/\b([45][0-9]{2})\b/);
    if (m) status = parseInt(m[1], 10);
  }
  return { failed: true, status, timedOut };
}

function failureCategory(f) {
  if (f.timedOut) return 'timeout';
  if (f.status === 401) return 'authentication';
  if (f.status === 403) return 'authorization';
  if (f.status !== null && f.status >= 500) return 'http_5xx';
  return 'provider_unavailable';
}

function failureConn(provider, connectionKey, base, f, times) {
  const denied = f.status === 401 || f.status === 403;
  return {
    recordType: 'provider_connection',
    idempotencyKey: base + ':conn',
    status: denied ? 'RED' : 'AMBER',
    severity: denied ? 'critical' : 'warning',
    payload: {
      provider,
      connectionKey,
      reachable: false,
      authorizationState: denied ? 'denied' : 'unknown',
      failureCategory: failureCategory(f)
    }
  };
}

function okConn(provider, connectionKey, base, observedAt) {
  return {
    recordType: 'provider_connection',
    idempotencyKey: base + ':conn',
    status: 'GREEN',
    severity: 'none',
    payload: {
      provider,
      connectionKey,
      reachable: true,
      authorizationState: 'ok',
      lastSuccessfulAt: observedAt
    }
  };
}

const depFail = failureOf(depResp);
const domFail = failureOf(domResp);

if (depFail.failed || domFail.failed) {
  const f = depFail.failed ? depFail : domFail;
  const record = failureConn('vercel', 'rest-api', config.base, f);
  return [{
    json: {
      observedAt: config.observedAt,
      publishedAt: config.publishedAt,
      freshUntil: config.freshUntil,
      records: [record],
      diagnostics: { deploymentsFailed: depFail.failed, domainsFailed: domFail.failed, status: f.status }
    }
  }];
}

// LIVE-FORMAT NOTE (2026-09-14): the deployments list endpoint is /v7
// (v13 was retired by Vercel with "Invalid API version"). v7 returns epoch
// MILLISECONDS in created/ready (not ISO createdAt/readyAt), so this helper
// accepts epoch-ms numbers / 11-16 digit numeric strings as well as ISO.
function isoOrNull(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return new Date(v).toISOString();
  if (typeof v !== 'string' && typeof v !== 'number') return null;
  if (/^d{11,16}$/.test(v)) return new Date(Number(v)).toISOString();
  const t = Date.parse(v);
  return Number.isFinite(t) ? new Date(t).toISOString() : null;
}

const DOMAIN_RE = /^[a-z0-9.-]+\.[a-z]{2,}$/;
const STATE_MAP = {
  ERROR: 'failed', CANCELED: 'cancelled', READY: 'ready',
  BUILDING: 'building', INITIALIZING: 'building', QUEUED: 'building'
};
const STATE_ENVELOPE = {
  ready: { status: 'GREEN', severity: 'none' },
  building: { status: 'GREEN', severity: 'info' },
  cancelled: { status: 'AMBER', severity: 'warning' },
  failed: { status: 'RED', severity: 'critical' },
  unknown: { status: 'UNKNOWN', severity: 'none' }
};

// --- keep production deployments only ----------------------------------------
const items = Array.isArray(depResp.deployments) ? depResp.deployments : [];
const kept = [];
let omittedNonTarget = 0; // VERIFY-ON-FIRST-RUN marker (non-production OR absent target)
for (const d of items) {
  if (!d || typeof d !== 'object') continue;
  if (!('target' in d) || d.target !== 'production') { omittedNonTarget++; continue; }
  kept.push(d);
}

// newest READY production deployment by createdAt
let newestReady = null;
for (const d of kept) {
  if (STATE_MAP[String(d.state).toUpperCase()] !== 'ready') continue;
  const t = Date.parse(isoOrNull(d.createdAt !== undefined && d.createdAt !== null ? d.createdAt : d.created) || 'invalid');
  if (Number.isFinite(t) && (newestReady === null || t > newestReady.t)) newestReady = { t, uid: d.uid };
}

const records = [];
for (const d of kept) {
  if (d.uid === undefined || d.uid === null) continue; // cannot key it — omit, never guess
  const state = STATE_MAP[String(d.state === undefined ? '' : d.state).toUpperCase()] || 'unknown';
  const createdAt = isoOrNull(d.createdAt !== undefined && d.createdAt !== null ? d.createdAt : d.created);
  const readyAt = isoOrNull(d.readyAt !== undefined && d.readyAt !== null ? d.readyAt : d.ready);
  let durationMs = null;
  if (createdAt !== null && readyAt !== null) {
    durationMs = Math.max(0, Date.parse(readyAt) - Date.parse(createdAt));
  }
  const aliases = Array.isArray(d.alias) ? d.alias : (Array.isArray(d.aliases) ? d.aliases : []);
  let publicDomainKey = null;
  for (const a of aliases) {
    const s = String(a).toLowerCase();
    if (DOMAIN_RE.test(s)) { publicDomainKey = s; break; }
  }

  const payload = {
    deploymentKey: String(d.uid),
    environment: 'production',
    state
  };
  if (createdAt !== null) payload.createdAt = createdAt;
  if (readyAt !== null) payload.readyAt = readyAt;
  if (durationMs !== null) payload.durationMs = durationMs;
  if (publicDomainKey !== null) payload.publicDomainKey = publicDomainKey;
  payload.isCurrentProduction = newestReady !== null && newestReady.uid === d.uid;
  if (state === 'failed') payload.failureCategory = 'provider_unavailable'; // provider-side build failure

  records.push({
    recordType: 'deployment_summary',
    idempotencyKey: config.base + ':dep:' + String(d.uid),
    ...STATE_ENVELOPE[state],
    payload
  });
}

// --- domains -> vercel.domain.verified metric samples -------------------------
const domItems = Array.isArray(domResp.domains) ? domResp.domains : [];
let domainsKept = 0;
for (const dm of domItems) {
  if (!dm || typeof dm !== 'object') continue;
  const name = String(dm.name === undefined ? '' : dm.name).toLowerCase();
  if (!DOMAIN_RE.test(name)) continue; // omit, never guess
  domainsKept++;
  records.push({
    recordType: 'metric_sample',
    idempotencyKey: config.base + ':domain:' + name,
    status: dm.verified === true ? 'GREEN' : 'AMBER',
    severity: dm.verified === true ? 'none' : 'warning',
    payload: {
      metricKey: 'vercel.domain.verified',
      sampledAt: config.observedAt,
      valueBoolean: dm.verified === true,
      unit: 'flag',
      periodStart: config.todayStart,
      periodEnd: config.todayEnd,
      coverage: 'full',
      dimensions: { domain: name }
    }
  });
}

records.push(okConn('vercel', 'rest-api', config.base, config.observedAt));

return [{
  json: {
    observedAt: config.observedAt,
    publishedAt: config.publishedAt,
    freshUntil: config.freshUntil,
    records,
    diagnostics: {
      deploymentsSeen: items.length,
      deploymentsKept: kept.length,
      deploymentsOmittedNonTarget: omittedNonTarget,
      domainsSeen: domItems.length,
      domainsKept
    }
  }
}];

// CloudIT - Vercel Deployments Collector — Build Records.
// Purpose: wrap the normalized records (produced by the Normalize node)
// in the strict Phase 0 section 7 evidence envelopes and attach the
// shared run timestamps from Load Config.
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).
// Envelope keys are exactly the Phase 0 contract: contractVersion "1.0",
// recordType, idempotencyKey (<=160 chars, opaque, unique per record),
// environmentKey "production", sourceSystem "vercel", observedAt,
// publishedAt, freshUntil, status, severity, correlationKey null, payload.
// Payload keys stay inside the strict allowlist of migration 0005 — any
// extra key rejects the WHOLE batch with unknown_field.

const input = $input.first().json;

const records = (Array.isArray(input.records) ? input.records : []).map((r) => ({
  contractVersion: '1.0',
  recordType: r.recordType,
  idempotencyKey: String(r.idempotencyKey),
  environmentKey: 'production',
  sourceSystem: 'vercel',
  observedAt: input.observedAt,
  publishedAt: input.publishedAt,
  freshUntil: input.freshUntil,
  status: r.status,
  severity: r.severity,
  correlationKey: null,
  payload: r.payload
}));

return [{
  json: {
    records,
    recordCount: records.length,
    publisherKey: 'cavetta-production-n8n'
  }
}];
